INSERT INTO p_studio_batch (id, act_id, num, br_batch_id, name, brief_json, setup_json, plan_json, status) VALUES ('955e149acf3af48d87fdaf4a', 'brand_bonk_golf', NULL, NULL, 'Black Friday: bundle + B2G1 hats (real photos only)', '{"angle": "Black Friday Nov 27 to 30: the five-piece set (hat, marker, divot tool, towel, tees) $125.75 of gear for $92.95, and Buy 2 Get 1 Free on hats only.", "why": "In BFCM 2025 the evergreen heroes beat the offer ads, so the gift and hero lines carry the offer; 325-2 (one price) and 235 B (gift line) are the strongest signals.", "concept": "Real bonkgolf.com photos only (Floyd: no AI imagery). Every line already has its finished image. Line 25 (unbox video) is not here: needs footage.", "post_copy": "Black Friday at BONK. The whole setup, hat, ball marker, divot tool, towel and tees, for $92.95. Or buy 2 hats and get 1 free. Nov 27 to 30.", "testing": "concepts", "lines": [{"text": "bf-01: Everything a golfer needs. Gift set photo, price.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7434c5acfc31e405db4982c2.png"}, {"text": "bf-02: Receipt: five pieces itemized, total struck, you pay.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/84cbd8c5f77c248191bcadf4.png"}, {"text": "bf-03: 5 pieces. 1 price. (325-2 rebuilt, dark).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6431fcf289db95f68de51ccf.png"}, {"text": "bf-04: Retire his old cap + the rest of the setup (235 B line).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6385039017728102d19de313.png"}, {"text": "bf-05: Skip the gift card (298-4 line).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/45c5ae4be68160a697a6a6ba.png"}, {"text": "bf-06: Review: used every piece.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2961d2bafffa86f0eea72215.png"}, {"text": "bf-07: One at a time vs the box.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/8583fd457052ba37f5418ba9.png"}, {"text": "bf-08: Black Friday, type-led, dark.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f512d830c002c238d8ec03e8.png"}, {"text": "bf-09: Every piece fits the hat (callouts).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/fbeecaef6082699bfc3beb08.png"}, {"text": "bf-10: You don''t need to know golf (to the gifter).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/df5f6b2eec84a4502623ba7a.png"}, {"text": "bf-11: Buy 2 hats, get 1 free. Three hats.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/eda15152c9ddbddcdae2a1ed.png"}, {"text": "bf-12: One for you, two for the group.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/a22e0e0b7bed090f7af2142e.png"}, {"text": "bf-13: Three gifts, pay for two.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/b7a6f1934ab7c7cb696548f6.png"}, {"text": "bf-14: Dad. Son. You. Youth hats count.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/5509805503872dbd06714975.png"}, {"text": "bf-15: All three black ones.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/d736747fdcdda1a733c595e4.png"}, {"text": "bf-16: Review: his and hers.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c52e2f6cd224286309d80236.png"}, {"text": "bf-17: Lefties count too (Southpaw).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7714c7ca9e353d28edecc8ec.png"}, {"text": "bf-18: Fitted counts too (PF 2.0, no sweat-stain claim).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/a325da4486435358893d453e.png"}, {"text": "bf-19: B2G1 type-led, dark.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/ad6171a611fec71bf0d724b3.png"}, {"text": "bf-20: Two deals, one card.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/1c97c404128b01f7d016fb21.png"}, {"text": "bf-21: Ends Monday (run Nov 29 to 30).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/ec5a6e1c8cf8e033f72148bf.png"}, {"text": "bf-22: Cyber Monday last day (run Nov 30 only).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6293c2a9d84de1346dd242a9.png"}, {"text": "bf-23: Sticker on ebf-01 (the anchor).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3a00d211c8542640144ea775.png"}, {"text": "bf-24: Sticker on ebf-06.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/d32b39acd4eb07ebfa40cff6.png"}], "source": "Bonk BFCM ads chat, 2026-10-14 (docs/bfcm-bonk-concepts.md, Batch 2)", "reference": "docs/bfcm-bonk-concepts.md"}', '{"products": [], "images": ["https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7434c5acfc31e405db4982c2.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/84cbd8c5f77c248191bcadf4.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6431fcf289db95f68de51ccf.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6385039017728102d19de313.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/45c5ae4be68160a697a6a6ba.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2961d2bafffa86f0eea72215.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/8583fd457052ba37f5418ba9.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f512d830c002c238d8ec03e8.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/fbeecaef6082699bfc3beb08.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/df5f6b2eec84a4502623ba7a.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/eda15152c9ddbddcdae2a1ed.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/a22e0e0b7bed090f7af2142e.png"], "swipe": []}', NULL, 'draft');
